    public async Task<IReadOnlyList<UpdateCandidate>> SearchUpdateCandidatesAsync(Guid productId, bool force, int cacheHours, CancellationToken token) { if(force)return []; var list=new List<UpdateCandidate>(); await using var c=await OpenAsync(token); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT provider_type,external_id,display_name,publisher_or_owner,latest_version,confidence,reason FROM update_candidate_cache WHERE product_id=$p AND resolved_utc >= $cutoff ORDER BY confidence,provider_type,external_id";cmd.Parameters.AddWithValue("$p",productId.ToString());cmd.Parameters.AddWithValue("$cutoff",DateTimeOffset.UtcNow.AddHours(-cacheHours).ToString("O"));await using var r=await cmd.ExecuteReaderAsync(token);while(await r.ReadAsync(token))list.Add(new(r.GetString(0),r.GetString(1),r.GetString(2),Text(r,3),Text(r,4),(MappingConfidence)r.GetInt32(5),r.GetString(6)));return list; }
    public async Task SaveUpdateCandidatesAsync(Guid productId, IReadOnlyList<UpdateCandidate> candidates, DateTimeOffset resolvedUtc, CancellationToken token) { await using var c=await OpenAsync(token);await using var t=await c.BeginTransactionAsync(token);await using(var clear=c.CreateCommand()){clear.Transaction=(SqliteTransaction)t;clear.CommandText="DELETE FROM update_candidate_cache WHERE product_id=$p";clear.Parameters.AddWithValue("$p",productId.ToString());await clear.ExecuteNonQueryAsync(token);}foreach(var candidate in candidates){await using var cmd=c.CreateCommand();cmd.Transaction=(SqliteTransaction)t;cmd.CommandText="INSERT INTO update_candidate_cache(product_id,provider_type,external_id,display_name,publisher_or_owner,latest_version,confidence,reason,resolved_utc) VALUES($p,$t,$e,$d,$o,$v,$c,$r,$u)";cmd.Parameters.AddWithValue("$p",productId.ToString());cmd.Parameters.AddWithValue("$t",candidate.ProviderType);cmd.Parameters.AddWithValue("$e",candidate.ExternalId);cmd.Parameters.AddWithValue("$d",candidate.DisplayName);cmd.Parameters.AddWithValue("$o",(object?)candidate.PublisherOrOwner??DBNull.Value);cmd.Parameters.AddWithValue("$v",(object?)candidate.LatestVersion??DBNull.Value);cmd.Parameters.AddWithValue("$c",(int)candidate.Confidence);cmd.Parameters.AddWithValue("$r",candidate.Reason);cmd.Parameters.AddWithValue("$u",resolvedUtc.ToString("O"));await cmd.ExecuteNonQueryAsync(token);}await t.CommitAsync(token); }
    public async Task ClearUpdateSourcesAsync(Guid productId, string providerType, CancellationToken token) { await using var c = await OpenAsync(token); await using var cmd = c.CreateCommand(); cmd.CommandText = "DELETE FROM product_update_sources WHERE product_id=$p AND provider_type=$t"; cmd.Parameters.AddWithValue("$p",productId.ToString()); cmd.Parameters.AddWithValue("$t",providerType); await cmd.ExecuteNonQueryAsync(token); }
    public async Task SaveUpdateCheckAsync(Guid id, UpdateCheckResult result, CancellationToken token) { await using var c = await OpenAsync(token); await using var cmd = c.CreateCommand(); cmd.CommandText = "UPDATE software_products SET update_status=$s,latest_version=$v,latest_normalized_version=$n,update_provider=$p,external_product_id=$e,last_checked_utc=$c,update_error=$r,updated_utc=$c WHERE id=$id"; cmd.Parameters.AddWithValue("$id",id.ToString()); cmd.Parameters.AddWithValue("$s",(int)result.Status); cmd.Parameters.AddWithValue("$v",(object?)result.LatestVersion??DBNull.Value); cmd.Parameters.AddWithValue("$n",(object?)result.LatestNormalizedVersion??DBNull.Value); cmd.Parameters.AddWithValue("$p",(object?)result.Source??DBNull.Value); cmd.Parameters.AddWithValue("$e",(object?)result.ExternalProductId??DBNull.Value); cmd.Parameters.AddWithValue("$c",(result.CheckedUtc??DateTimeOffset.UtcNow).ToString("O")); cmd.Parameters.AddWithValue("$r",(object?)result.Error??DBNull.Value); await cmd.ExecuteNonQueryAsync(token); }
    public async Task SaveDownloadHistoryAsync(DownloadHistory h, CancellationToken token) { await using var c = await OpenAsync(token); await using var cmd = c.CreateCommand(); cmd.CommandText = "INSERT INTO download_history(id,product_id,provider_type,external_product_id,version,file_name,source_url,expected_sha256,actual_sha256,status,error,started_utc,completed_utc,final_relative_path) VALUES($id,$p,$pt,$e,$v,$f,$u,$x,$a,$s,$r,$st,$c,$q) ON CONFLICT(id) DO UPDATE SET actual_sha256=excluded.actual_sha256,status=excluded.status,error=excluded.error,completed_utc=excluded.completed_utc,final_relative_path=excluded.final_relative_path"; cmd.Parameters.AddWithValue("$id",h.Id.ToString()); cmd.Parameters.AddWithValue("$p",h.ProductId.ToString()); cmd.Parameters.AddWithValue("$pt",h.ProviderType); cmd.Parameters.AddWithValue("$e",h.ExternalProductId); cmd.Parameters.AddWithValue("$v",(object?)h.Version??DBNull.Value); cmd.Parameters.AddWithValue("$f",(object?)h.FileName??DBNull.Value); cmd.Parameters.AddWithValue("$u",(object?)h.SourceUrl??DBNull.Value); cmd.Parameters.AddWithValue("$x",(object?)h.ExpectedSha256??DBNull.Value); cmd.Parameters.AddWithValue("$a",(object?)h.ActualSha256??DBNull.Value); cmd.Parameters.AddWithValue("$s",(int)h.Status); cmd.Parameters.AddWithValue("$r",(object?)h.Error??DBNull.Value); cmd.Parameters.AddWithValue("$st",h.StartedUtc.ToString("O")); cmd.Parameters.AddWithValue("$c",h.CompletedUtc?.ToString("O")??(object)DBNull.Value); cmd.Parameters.AddWithValue("$q",(object?)h.FinalRelativePath??DBNull.Value); await cmd.ExecuteNonQueryAsync(token); }
    public async Task<IReadOnlyList<DownloadHistory>> GetDownloadHistoryAsync(CancellationToken token) { var list = new List<DownloadHistory>(); await using var c = await OpenAsync(token); await using var cmd = c.CreateCommand(); cmd.CommandText = "SELECT id,product_id,provider_type,external_product_id,version,file_name,source_url,expected_sha256,actual_sha256,status,error,started_utc,completed_utc,final_relative_path FROM download_history ORDER BY started_utc DESC"; await using var r = await cmd.ExecuteReaderAsync(token); while(await r.ReadAsync(token)) list.Add(new(Guid.Parse(r.GetString(0)),Guid.Parse(r.GetString(1)),r.GetString(2),r.GetString(3),Text(r,4),Text(r,5),Text(r,6),Text(r,7),Text(r,8),(DownloadStatus)r.GetInt32(9),Text(r,10),DateTimeOffset.Parse(r.GetString(11)),r.IsDBNull(12)?null:DateTimeOffset.Parse(r.GetString(12)),Text(r,13))); return list; }
    public async Task<bool> HasInstallerSha256Async(string hash, CancellationToken token) { await using var c = await OpenAsync(token); await using var cmd = c.CreateCommand(); cmd.CommandText = "SELECT EXISTS(SELECT 1 FROM installer_files WHERE sha256=$h)"; cmd.Parameters.AddWithValue("$h", hash); return Convert.ToInt64(await cmd.ExecuteScalarAsync(token)) != 0; }
    private async Task<SqliteConnection> OpenAsync(CancellationToken token) { var c = new SqliteConnection(_connectionString); await c.OpenAsync(token); await using var cmd = c.CreateCommand(); cmd.CommandText = "PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000;"; await cmd.ExecuteNonQueryAsync(token); return c; }
